CREATE TABLE IF NOT EXISTS esun_proyectos (id text PRIMARY KEY, created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL, updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL, client_name text, cfe_data jsonb, proposals jsonb, status text); ALTER TABLE esun_proyectos ENABLE ROW LEVEL SECURITY; CREATE POLICY "Enable read access for all users" ON esun_proyectos FOR SELECT USING (true); CREATE POLICY "Enable insert access for all users" ON esun_proyectos FOR INSERT WITH CHECK (true); CREATE POLICY "Enable update access for all users" ON esun_proyectos FOR UPDATE USING (true); CREATE POLICY "Enable delete access for all users" ON esun_proyectos FOR DELETE USING (true);
